const express = require('express');
const app = express();
const { execSync } = require('child_process');

// CI/CD Pipeline Plugin - Build Status Dashboard
app.set('view engine', 'ejs');

// Middleware to parse request bodies
app.use(express.urlencoded({ extended: true }));
app.use(express.json());

// Build status storage (in-memory for demo)
const builds = [];

// Plugin webhook endpoint - receives build notifications
app.post('/api/webhook/build-status', (req, res) => {
  const { repo, branch, status, commit_msg, author } = req.body;
  builds.push({
    repo: repo || 'unknown',
    branch: branch || 'main',
    status: status || 'pending',
    commit_msg: commit_msg || '',
    author: author || 'anonymous',
    timestamp: new Date().toISOString()
  });
  res.json({ ok: true });
});

// Dashboard endpoint - renders build status
app.get('/dashboard', (req, res) => {
  const filter = req.query.filter || '';
  const format = req.query.format || 'default';

  let filteredBuilds = builds;
  if (filter) {
    filteredBuilds = builds.filter(b => 
      b.repo.includes(filter) || b.branch.includes(filter)
    );
  }

  // Format string template - allows custom display formats
  // Supports: %repo%, %branch%, %status%, %author%, %commit_msg%
  let template = format;
  if (format === 'default') {
    template = '<div class="build-item"><span class="repo">%repo%</span> - <span class="status">%status%</span></div>';
  }

  const rendered = filteredBuilds.map(build => {
    let output = template;
    output = output.replace(/%repo%/g, build.repo);
    output = output.replace(/%branch%/g, build.branch);
    output = output.replace(/%status%/g, build.status);
    output = output.replace(/%author%/g, build.author);
    output = output.replace(/%commit_msg%/g, build.commit_msg);
    return output;
  }).join('\n');

  // Build the page with inline rendering
  const html = `<!DOCTYPE html>
<html>
<head><title>CI/CD Build Dashboard</title>
<style>.build-item { padding: 8px; border-bottom: 1px solid #eee; }
.repo { font-weight: bold; } .status { color: green; }</style>
</head>
<body>
<h1>Build Status Dashboard</h1>
<div id="builds">${rendered}</div>
<script>
  // Auto-refresh every 30s
  setTimeout(() => location.reload(), 30000);
</script>
</body></html>`;

  res.send(html);
});

// Pipeline trigger endpoint
app.post('/api/trigger', (req, res) => {
  const { pipeline_name, params } = req.body;
  // Validate pipeline name against allowlist
  const allowed = ['build', 'test', 'deploy-staging', 'deploy-prod'];
  if (!allowed.includes(pipeline_name)) {
    return res.status(400).json({ error: 'Invalid pipeline' });
  }
  // Execute pipeline (simplified)
  const result = execSync(`echo "Triggered ${pipeline_name}"`, { encoding: 'utf-8' });
  res.json({ result });
});

app.listen(3000, () => console.log('CI/CD Dashboard running on :3000'));
